def reorder(t):
    old = "    if (!Number.isSafeInteger(Number(item.quantity)) || !(typeof item.quantity === \"number\" || typeof item.quantity === \"string\") || Number(item.quantity) > 1000000 || !decimal(item.unitPrice,9999999999.99))"
    new = "    if (!(typeof item.quantity === \"number\" || typeof item.quantity === \"string\") || !Number.isSafeInteger(Number(item.quantity)) || Number(item.quantity) > 1000000 || !decimal(item.unitPrice,9999999999.99))"
    assert old in t
    return t.replace(old, new, 1)
fe.rw('server/src/index.ts', reorder); done.append('review#3 quantity guard checks the shape (typeof) before the value (isSafeInteger), matching the order the course teaches')
def patch_test(t):
    add = '''
test("two units at 12.34 with zero tax total 24.68, and the total is stored to the cent", async () => {
  const client = (await call("/api/clients")).data[0];
  const made = await call("/api/invoices", "POST", {
    clientId: client.id, status: "draft", issuedDate: "2028-02-29", taxRate: 0,
    items: [{ description: "Lesson", quantity: 2, unitPrice: 12.34 }],
  });
  assert.equal(made.status, 201, JSON.stringify(made.data));
  const read = (await call("/api/invoices/" + made.data.id)).data;
  assert.equal(read.total, 24.68);
  assert.equal(read.issuedDate, "2028-02-29");
});
'''
    return t.rstrip('\n') + '\n' + add
