def rewrite02(t):
    t = fe.replace_section(t, r'Validation versus normalization', """Money and dates are where this project earns its keep. `decimal(value, maximum)` (`server/src/index.ts:272`) accepts a number or a string that matches `/^\\d+(?:\\.\\d{1,2})?$/` and is at most `maximum`: so `'2.50'`, `2.5` and `12.34` pass, `0.001` (three decimals), `-1` (sign), `1e3` (exponent) and `' 2'` (whitespace) fail. Normalization then converts with `Number(...)`. The quantity guard checks the shape first (`typeof`) and the value second (`Number.isSafeInteger`, the upper bound). The issue date is a calendar label validated by round-tripping through `Date.parse` and `toISOString`, so `2027-02-29` (not a leap year) is rejected while `2028-02-29` is kept.""") or t
    t = fe.replace_section(t, r'Identity, representation and derived values', """PostgreSQL stores `unit_price`, `subtotal`, `tax` and `total` as `numeric(12,2)`: exact decimal, two places. JavaScript has one `number` type, binary floating point: `0.1 * 2 * 1.1` is `0.22000000000000003`. The two disagree exactly where invoices care. The rule this project follows: compute in JavaScript, then `Math.round(x * 100) / 100` *before* the value is stored or shown, so the number that reaches `numeric(12,2)` is already a cent value and the column does not round silently. The first test's fixture (`0.1 x 2 at 10%`) and the new fourth test (`12.34 x 2 at 0%`, total `24.68`) are the two ends of that rule. Exercise 4 goes further: store integer cents and never let a float near money.""") or t
    return t
fe.rw(fe.chapter(S, '02'), rewrite02); done.append('review#1 02 sections rewritten around decimal(), numeric vs number, and the round-before-store rule')
